export function getPersonaCantItem(id: string): PersonaCantItem | undefined {
  return PERSONA_CANT_ITEMS.find((item) => item.id === id);
}

export function getPersonaFurnishItem(id: string): PersonaFurnishItem | undefined {
  return PERSONA_FURNISH_ITEMS.find((item) => item.id === id);
}

export function getPersonaCantsForSubject(subjectId: string): PersonaCantItem[] {
  return PERSONA_CANT_ITEMS.filter((item) => item.subjectId === subjectId);
}

export function getPersonaFurnishForSubject(subjectId: string): PersonaFurnishItem[] {
  return PERSONA_FURNISH_ITEMS.filter((item) => item.subjectId === subjectId);
}
